// v0.10 path interno. Extrae keywords del mensaje del usuario interno.
// Remueve stopwords típicas de consulta de precio.
const STOPWORDS = new Set([
  'cuanto','cuánto','sale','vale','precio','precios','es','el','la','los','las',
  'de','del','un','una','tienen','hay','como','cómo','que','qué','para','en',
  'me','pasas','pasame','decime','digo','che','dale','un','dame','tenes','tenés',
  'tienes','con','y','o','a','al'
]);

const ctx = $('Execute Workflow Trigger').first().json;
const raw = String(ctx.mensajeActual || '').trim();
const normalized = raw
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const tokens = normalized.split(' ').filter(t => t.length >= 2 && !STOPWORDS.has(t));

return [{ json: {
  query_original: raw,
  query_normalized: normalized,
  keywords: tokens,
  subId: ctx.subId,
  canal: ctx.canalLabel || 'WhatsApp',
  sessionKey: ctx.sessionKey
} }];

// v0.10 path interno. Filtra rows por keywords AND across all columns.
// Devuelve top 5 formateado en texto plano.
const rows = $input.all();
const ctx = $('Extract keywords').first().json;
const keywords = ctx.keywords || [];
const query = ctx.query_original || '';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Si query queda sin keywords (todo stopwords) — pedir más info
if (keywords.length === 0) {
  return [{ json: {
    status: 'EMPTY_QUERY',
    matches_count: 0,
    items: [],
    mensaje: 'Necesito un modelo, marca o tecnología específica para buscar. Ej.: "HUENU UV" o "DTF textil".',
    query
  } }];
}

const matches = rows.filter(r => {
  const concatenated = normalize(Object.values(r.json).join(' '));
  return keywords.every(k => concatenated.includes(k));
});

if (matches.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    matches_count: 0,
    items: [],
    mensaje: `No encontré nada que matchee "${query}". Probá con otro modelo o marca.`,
    query
  } }];
}

const top = matches.slice(0, 5).map(r => r.json);

// Formato adaptativo: muestra las columnas que tienen valor, en orden de definición del sheet.
function formatRow(row, idx) {
  const lines = [`${idx + 1}. ` + Object.values(row).filter(v => v).slice(0, 2).join(' — ')];
  const rest = Object.entries(row)
    .filter(([k, v]) => v != null && String(v).trim() !== '')
    .slice(2);
  for (const [k, v] of rest) {
    lines.push(`   ${k}: ${v}`);
  }
  return lines.join('\n');
}

const header = matches.length > 5
  ? `Encontré ${matches.length} resultados para "${query}", te paso los primeros 5. Afiná con marca o modelo si querés ver más.`
  : `Encontré ${matches.length} ${matches.length === 1 ? 'match' : 'matches'} para "${query}":`;

const body = top.map(formatRow).join('\n\n');
const mensaje = `${header}\n\n${body}`;

return [{ json: {
  status: matches.length > 5 ? 'AMBIGUOUS' : 'RESOLVED',
  matches_count: matches.length,
  items: top,
  mensaje,
  query
} }];

